/// Default statistics in original units.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Euptf2WpStatistics {
    /// WP: original-scale point estimate. Ranger means are aggregated on the fitted scale before the original back-transform; M is derived only for means. (cm^3/cm^3)
    pub mean: f64,
    /// WP: conditional quantile at probability 0.05; type-7 interpolation of stored terminal response samples, then original back-transform. (cm^3/cm^3)
    pub q05: f64,
    /// WP: conditional quantile at probability 0.25; type-7 interpolation of stored terminal response samples, then original back-transform. (cm^3/cm^3)
    pub q25: f64,
    /// WP: conditional quantile at probability 0.5; type-7 interpolation of stored terminal response samples, then original back-transform. (cm^3/cm^3)
    pub q50: f64,
    /// WP: conditional quantile at probability 0.75; type-7 interpolation of stored terminal response samples, then original back-transform. (cm^3/cm^3)
    pub q75: f64,
    /// WP: conditional quantile at probability 0.95; type-7 interpolation of stored terminal response samples, then original back-transform. (cm^3/cm^3)
    pub q95: f64,
}
